// Independent native replay of the frozen larger-curve S4 producer output.
// The producer's phase-0 gate remains censored; any solve here is diagnostic.
use std::fs;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]struct Pt{x:i64,y:i64}
type Point=Option<Pt>;
fn m(x:i64,n:i64)->i64{x.rem_euclid(n)}
fn pow(mut a:i64,mut e:i64,p:i64)->i64{let mut z=1;while e>0{if e&1!=0{z=m(z*a,p)}a=m(a*a,p);e>>=1}z}
fn inv(a:i64,p:i64)->i64{assert_ne!(m(a,p),0);pow(m(a,p),p-2,p)}
fn neg(q:Point,p:i64)->Point{q.map(|v|Pt{x:v.x,y:m(-v.y,p)})}
fn add(s:Point,t:Point,p:i64,a:i64)->Point{match(s,t){(None,q)|(q,None)=>q,(Some(u),Some(v))=>{if u.x==v.x&&m(u.y+v.y,p)==0{return None}let k=if u==v{m((3*u.x*u.x+a)*inv(2*u.y,p),p)}else{m((v.y-u.y)*inv(v.x-u.x,p),p)};let x=m(k*k-u.x-v.x,p);Some(Pt{x,y:m(k*(u.x-x)-u.y,p)})}}}
fn mul(mut q:Point,mut k:i64,p:i64,a:i64)->Point{let mut out=None;while k>0{if k&1!=0{out=add(out,q,p,a)}q=add(q,q,p,a);k>>=1}out}
fn on(q:Pt,p:i64,a:i64,b:i64)->bool{m(q.y*q.y-q.x*q.x*q.x-a*q.x-b,p)==0}
fn lift_min(x:i64,p:i64,a:i64,b:i64)->Option<Pt>{let y2=m(x*x*x+a*x+b,p);(0..p).find(|&y|m(y*y,p)==y2).map(|y|Pt{x,y})}
fn key(line:&str,k:&str)->i64{line.split_whitespace().find_map(|w|w.strip_prefix(k)).unwrap_or_else(||panic!("missing key {k}: {line}")).trim_end_matches(',').parse().unwrap()}
fn bracket(line:&str,k:&str)->Vec<i64>{let start=format!("{k}=[");line.split(&start).nth(1).unwrap().split(']').next().unwrap().split(',').map(|x|x.trim().parse().unwrap()).collect()}
fn point(line:&str,k:&str)->Pt{let start=format!("{k}=[Mod(");let q=line.split(&start).nth(1).unwrap();let x=q.split(',').next().unwrap().parse().unwrap();let y=q.split("), Mod(").nth(1).unwrap().split(',').next().unwrap().parse().unwrap();Pt{x,y}}
#[derive(Clone)]struct Target{u:i64,v:i64,x:i64,zeros:usize,witness:usize}
#[derive(Clone)]struct Rel{u:i64,v:i64,i:usize,j:usize,k:usize,mask:usize}
struct Case{p:i64,a:i64,b:i64,r:i64,g:Pt,q:Pt,bx:Vec<i64>,targets:Vec<Target>,rels:Vec<Rel>,phase0:i64,final_rank:i64,rho_log:i64,rho_iter:i64,reported_targets:i64}
fn parse(path:&str)->Vec<Case>{let raw=fs::read_to_string(path).unwrap();let mut cases:Vec<Case>=Vec::new();for line in raw.lines(){if line.starts_with("header "){cases.push(Case{p:key(line,"p="),a:key(line,"a="),b:key(line,"b="),r:key(line,"order="),g:point(line,"G"),q:point(line,"Q"),bx:bracket(line,"base_x"),targets:Vec::new(),rels:Vec::new(),phase0:-1,final_rank:-1,rho_log:-1,rho_iter:-1,reported_targets:-1})}else if line.starts_with("target a="){let c=cases.last_mut().unwrap();c.targets.push(Target{u:key(line,"a="),v:key(line,"b="),x:key(line,"x="),zeros:key(line,"S4_zero_triples=") as usize,witness:key(line,"signed_witnesses=") as usize})}else if line.starts_with("rel="){let nums:Vec<i64>=line.strip_prefix("rel=[").unwrap().trim_end_matches(']').split(',').map(|x|x.trim().parse().unwrap()).collect();let c=cases.last_mut().unwrap();c.rels.push(Rel{u:nums[0],v:nums[1],i:nums[2] as usize,j:nums[3] as usize,k:nums[4] as usize,mask:nums[5] as usize})}else if line.starts_with("ic_summary "){let c=cases.last_mut().unwrap();c.phase0=key(line,"phase0_rank=");c.final_rank=key(line,"final_rank=");c.reported_targets=key(line,"targets=")}else if line.starts_with("rho_summary "){let c=cases.last_mut().unwrap();c.rho_log=key(line,"target_log=");c.rho_iter=key(line,"iterations=")}}assert_eq!(cases.len(),2);cases}
fn s4zero(x:i64,y:i64,w:i64,z:i64,p:i64,a:i64,b:i64)->bool{let aa=m((x-y)*(x-y),p);let bb=m(-2*((x+y)*(x*y+a)+2*b),p);let cc=m((x*y-a)*(x*y-a)-4*b*(x+y),p);let dd=m((z-w)*(z-w),p);let ee=m(-2*w*z*z-2*(w*w+a)*z-2*a*w-4*b,p);let ff=m(w*w*z*z-2*(a*w+2*b)*z+a*a-4*b*w,p);m(m(aa*ff-cc*dd,p).pow(2)-m(aa*ee-bb*dd,p)*m(bb*ff-cc*ee,p),p)==0}
fn rank(mut a:Vec<Vec<i64>>,r:i64,solve:bool)->(usize,Vec<i64>){let mut h=0;let n=17;for col in 0..n{if h==a.len(){break}let found=(h..a.len()).find(|&i|a[i][col]!=0);if let Some(i)=found{a.swap(h,i);let z=inv(a[h][col],r);for j in col..a[h].len(){a[h][j]=m(a[h][j]*z,r)}let row=a[h].clone();for i in 0..a.len(){if i!=h{let t=a[i][col];if t!=0{for j in col..a[i].len(){a[i][j]=m(a[i][j]-t*row[j],r)}}}}h+=1}}let mut logs=Vec::new();if solve{assert_eq!(h,n);assert!(a.iter().skip(n).all(|row|row.iter().all(|&v|v==0)));logs=(0..n).map(|i|a[i][n]).collect()}(h,logs)}
fn rho(c:&Case)->(i64,i64){let p=c.p;let a=c.a;let r=c.r;let g=Some(c.g);let q=Some(c.q);let step=|s:(Point,i64,i64)|{let bucket=s.0.map(|x|x.x%3).unwrap_or(0);if bucket==0{(add(s.0,g,p,a),m(s.1+1,r),s.2)}else if bucket==1{(add(s.0,q,p,a),s.1,m(s.2+1,r))}else{(add(s.0,s.0,p,a),m(2*s.1,r),m(2*s.2,r))}};let start=(add(g,q,p,a),1,1);let(mut slow,mut fast)=(start,start);for iter in 1..=10000{slow=step(slow);fast=step(step(fast));if slow.0==fast.0{let den=m(slow.2-fast.2,r);assert_ne!(den,0,"degenerate rho diagnostic");let d=m((fast.1-slow.1)*inv(den,r),r);assert_eq!(mul(g,d,p,a),q);return(iter,d)}}panic!("rho cap diagnostic")}
fn verify(c:&Case){let(p,a,b,r)=(c.p,c.a,c.b,c.r);assert!([10007,20011].contains(&p));assert_eq!(pow(2,p-1,p),1);assert_eq!(c.bx.len(),16);let mut card=1;for x in 0..p{let y2=m(x*x*x+a*x+b,p);card+=if y2==0{1}else if pow(y2,(p-1)/2,p)==1{2}else{0}}assert_eq!(card,r);assert!(on(c.g,p,a,b)&&on(c.q,p,a,b));assert_eq!(mul(Some(c.g),r,p,a),None);assert_eq!(mul(Some(c.q),r,p,a),None);assert_eq!(lift_min(0,p,a,b),Some(c.g));let mut base=Vec::new();let mut xx=1;while base.len()<16{if let Some(v)=lift_min(xx,p,a,b){base.push(Some(v));assert_eq!(xx,c.bx[base.len()-1])}xx+=1}while lift_min(xx,p,a,b).is_none(){xx+=1}assert_eq!(lift_min(xx,p,a,b),Some(c.q));
 let mut sums=Vec::with_capacity(16*16*16*8);for i in 0..16{for j in 0..16{for k in 0..16{for mask in 0..8{let f=|h:usize,bit:usize|if mask&(1<<bit)==0{base[h]}else{neg(base[h],p)};sums.push(add(add(f(i,0),f(j,1),p,a),f(k,2),p,a))}}}}let mut all_zero=0;let mut all_witness=0;for t in &c.targets{let target=add(mul(Some(c.g),t.u,p,a),mul(Some(c.q),t.v,p,a),p,a).unwrap();assert_eq!(target.x,t.x);let(mut z,mut w)=(0,0);for i in 0..16{for j in 0..16{for k in 0..16{let zero=s4zero(c.bx[i],c.bx[j],c.bx[k],t.x,p,a,b);let off=((i*16+j)*16+k)*8;let found=(0..8).filter(|&mask|sums[off+mask]==Some(target)).count();assert_eq!(zero,found>0,"S4/group mismatch p={p} u={} v={} i={i} j={j} k={k}",t.u,t.v);z+=usize::from(zero);w+=found}}}assert_eq!(z,t.zeros);assert_eq!(w,t.witness);all_zero+=z;all_witness+=w;println!("verified_target p={p} u={} v={} x={} zeros={z} witnesses={w}",t.u,t.v,t.x)}
 let mut matrix=Vec::new();let mut phase0=Vec::new();for rel in &c.rels{assert!((1..=16).contains(&rel.i)&&(1..=16).contains(&rel.j)&&(1..=16).contains(&rel.k)&&rel.mask<8);let rpoint=add(mul(Some(c.g),rel.u,p,a),mul(Some(c.q),rel.v,p,a),p,a);let off=(((rel.i-1)*16+rel.j-1)*16+rel.k-1)*8+rel.mask;assert_eq!(sums[off],rpoint);let mut row=vec![0;18];for (idx,bit) in [(rel.i,0),(rel.j,1),(rel.k,2)]{row[idx-1]=m(row[idx-1]+if rel.mask&(1<<bit)==0{1}else{-1},r)}row[16]=m(-rel.v,r);row[17]=m(rel.u,r);if rel.v==0{phase0.push(row.clone())}matrix.push(row)}let phase_rank=rank(phase0,r,false).0;let (full_rank,logs)=rank(matrix.clone(),r,true);assert_eq!(phase_rank as i64,c.phase0);assert_eq!(full_rank as i64,c.final_rank);assert!(phase_rank<16);assert_eq!(full_rank,17);for i in 0..16{assert_eq!(mul(Some(c.g),logs[i],p,a),base[i])}assert_eq!(mul(Some(c.g),logs[16],p,a),Some(c.q));for row in &matrix{let z=(0..17).fold(0,|acc,j|m(acc+row[j]*logs[j],r));assert_eq!(z,row[17])}let (rho_iter,rho_d)=rho(c);assert_eq!(rho_iter,c.rho_iter);assert_eq!(rho_d,c.rho_log);assert_eq!(rho_d,logs[16]);assert_eq!(c.reported_targets as usize,c.targets.len());println!("verify_summary p={p} order={r} targets={} cells={} signed_patterns={} S4_zeros={all_zero} witnesses={all_witness} phase0_rank={phase_rank} full_rank={full_rank} diagnostic_log={} rho_iter={rho_iter} rho_log={rho_d} producer_gate=censored all_fullgrid_equivalences=true",c.targets.len(),c.targets.len()*4096,c.targets.len()*32768,logs[16])}
fn main(){let path="research/prime_field_100_ideas_20261123/EC_S4_LARGER_024/producer.stdout";let cases=parse(path);for c in &cases{verify(c)}println!("complete independent larger EC S4 replay");}
